// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($env.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($env.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

const dedupe_key = 'digest:' + d.dedupe_date;

// Work before numbers: a dashboard that only reports is a dashboard you stop
// opening. Everything in this list is a decision waiting on you.
const todo = [];
if (Number(d.partners_pending)   > 0) todo.push(d.partners_pending + ' partner application(s) waiting');
if (Number(d.orders_stuck)       > 0) todo.push(d.orders_stuck + ' order(s) stuck pending');
if (Number(d.orders_failed_24h)  > 0) todo.push(d.orders_failed_24h + ' payment(s) failed yesterday');
if (Number(d.blessings_awaiting) > 0) todo.push(d.blessings_awaiting + ' blessing(s) awaiting moderation');

const top = (d.top_invites || []).map((t) =>
  '<li><a href="' + site + '/invite/' + esc(t.slug) + '" style="color:' + brand + ';">'
  + esc(t.title) + '</a> \u2014 ' + t.views + ' views</li>').join('');

const bodyHtml = `
  ${todo.length
    ? `<div style="background:#fff5f3;border-left:3px solid ${brand};padding:12px 16px;border-radius:6px;margin:0 0 22px;">
        <div style="font-weight:600;color:#1f1a19;margin-bottom:6px;">Needs you</div>
        <ul style="margin:0;padding-left:18px;">${todo.map((t) => '<li>' + esc(t) + '</li>').join('')}</ul>
       </div>`
    : '<p style="margin:0 0 20px;color:#6b615e;">Nothing needs a decision from you today.</p>'}

  <div style="margin:0 0 8px;font-weight:600;color:#1f1a19;">Yesterday</div>
  <div style="margin:0 0 22px;">
    ${stat('Revenue', inr(d.revenue_24h))}${stat('Signups', d.signups_24h)}${stat('Published', d.published_24h)}
    ${stat('New invites', d.invites_created_24h)}${stat('Views', d.views_24h)}${stat('RSVPs', d.rsvps_24h)}
  </div>

  <div style="margin:0 0 8px;font-weight:600;color:#1f1a19;">Standing</div>
  <div style="margin:0 0 22px;">
    ${stat('Revenue 30d', inr(d.revenue_30d))}${stat('All time', inr(d.revenue_all))}
    ${stat('Commission owed', inr(d.commission_owed))}${stat('Drafts open', d.drafts_open)}
    ${stat('Published total', d.published_total)}${stat('Signups 7d', d.signups_7d)}
  </div>

  ${top ? '<div style="margin:0 0 8px;font-weight:600;color:#1f1a19;">Most viewed yesterday</div><ol style="margin:0;padding-left:20px;">' + top + '</ol>' : ''}`;

const summary = 'revenue ' + inr(d.revenue_24h) + ', ' + d.signups_24h + ' signups, '
  + d.published_24h + ' published, ' + d.views_24h + ' views';

return { json: {
  dedupe_key,
  to: '',
  stored: {
    report_date: d.report_date,
    dedupe_key,
    revenue_24h: d.revenue_24h,
    signups_24h: d.signups_24h,
    published_24h: d.published_24h,
    todo,
    subject: 'Amantrika daily \u2014 ' + inr(d.revenue_24h) + ', ' + d.signups_24h + ' signups, ' + d.published_24h + ' published',
    whatsapp: 'Daily ' + d.report_date + ': ' + summary + '.'
      + (todo.length ? ' Needs you: ' + todo.join('; ') + '.' : '') + ' ' + site + '/admin',
    html: shell('Daily digest \u00b7 ' + d.report_date, bodyHtml, 'Open admin', site + '/admin', null),
    text: 'Amantrika daily \u2014 ' + d.report_date + '\n' + summary + '\n' + todo.join('\n') + '\n' + site + '/admin',
  },
} };

